('ielts-b2-spk2-045', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'speaking', 'ielts-speaking-part2', 'Speaking Part 2 (Cue Card)', 'An Exciting Book You Read', 'Describe an exciting book that you have read. You should say: what the book was; when you read it; what it was about; and explain why you found it exciting. You have one minute to prepare and may make notes. Speak for one to two minutes.', 120, 60, 15, 'medium', ARRAY['Original practice', 'IELTS', 'Speaking'], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
