('ielts-b2-lmcq-001', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Changing a flight', 'Which day will the traveller fly? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "I''ll take the Tuesday flight". The answer is A: Tuesday', NULL, NULL, 'Agent: Your flight to Lisbon on Monday is full, so we can''t move you to that one. There''s a seat on Tuesday morning, and one on Wednesday evening. Traveller: I have a meeting on Wednesday, so I''ll take the Tuesday flight. Agent: Tuesday morning it is.', NULL, NULL, '["A"]'::jsonb, '[{"id": "A", "text": "Tuesday"}, {"id": "B", "text": "Wednesday"}, {"id": "C", "text": "Monday"}]'::jsonb),
('ielts-b2-lmcq-002', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Choosing a gym class', 'Which class has the man chosen? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "signed up for the swimming fitness class". The answer is A: swimming fitness', NULL, NULL, 'Man: I thought about yoga, but the times don''t suit me, and spinning looks too intense. So I''ve signed up for the swimming fitness class on Thursday evenings.', NULL, NULL, '["A"]'::jsonb, '[{"id": "A", "text": "swimming fitness"}, {"id": "B", "text": "yoga"}, {"id": "C", "text": "spinning"}]'::jsonb),
('ielts-b2-lmcq-003', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Why the concert moved', 'Why was the concert moved? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "failed its safety inspection". The answer is B: The stage failed a safety check.', NULL, NULL, 'Organiser: Many people assume the concert moved because of ticket sales, but we sold out in a week. The real reason is that the park''s stage failed its safety inspection, so we''ve moved to the town hall.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "Not enough tickets were sold."}, {"id": "B", "text": "The stage failed a safety check."}, {"id": "C", "text": "The weather was too bad."}]'::jsonb),
('ielts-b2-lmcq-004', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Cheapest way to the airport', 'What is the cheapest way to the airport? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "the cheapest option is the number seven bus". The answer is B: bus', NULL, NULL, 'Assistant: A taxi costs about fifty dollars, and the express train is twenty. But the cheapest option is the number seven bus, which is only four dollars, although it takes an hour.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "express train"}, {"id": "B", "text": "bus"}, {"id": "C", "text": "taxi"}]'::jsonb),
('ielts-b2-lmcq-005', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'A new library service', 'What is new at the library this year? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "members can borrow tools". The answer is C: lending tools', NULL, NULL, 'Librarian: We''ve always lent books and DVDs, of course. What''s new this year is that members can borrow tools, such as drills and ladders, for up to a week.', NULL, NULL, '["C"]'::jsonb, '[{"id": "A", "text": "longer loan periods"}, {"id": "B", "text": "lending DVDs"}, {"id": "C", "text": "lending tools"}]'::jsonb),
('ielts-b2-lmcq-006', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Problem with a delivery', 'What is wrong with the sofa? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "one of the legs is broken". The answer is C: It is damaged.', NULL, NULL, 'Customer: The sofa arrived on time and the colour is right. The problem is that one of the legs is broken, so it isn''t safe to sit on.', NULL, NULL, '["C"]'::jsonb, '[{"id": "A", "text": "It arrived late."}, {"id": "B", "text": "It is the wrong colour."}, {"id": "C", "text": "It is damaged."}]'::jsonb),
('ielts-b2-lmcq-007', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Research method chosen', 'Which research method did the students choose? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "we chose an online questionnaire". The answer is B: an online questionnaire', NULL, NULL, 'Student: We considered interviews, but they take so long to transcribe. Observation wasn''t practical in a hospital. In the end we chose an online questionnaire, which reached far more nurses.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "observation"}, {"id": "B", "text": "an online questionnaire"}, {"id": "C", "text": "interviews"}]'::jsonb),
('ielts-b2-lmcq-008', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Most popular exhibit', 'Which exhibit do visitors enjoy most? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "the one people enjoy most is the interactive weather room". The answer is C: the weather room', NULL, NULL, 'Guide: Visitors often expect the dinosaur skeleton to be our most popular exhibit, and it''s certainly impressive. But according to our surveys, the one people enjoy most is the interactive weather room.', NULL, NULL, '["C"]'::jsonb, '[{"id": "A", "text": "the space gallery"}, {"id": "B", "text": "the dinosaur skeleton"}, {"id": "C", "text": "the weather room"}]'::jsonb),
('ielts-b2-lmcq-009', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Reason for a late essay', 'Why was the essay late? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "couldn''t get hold of two of the books". The answer is C: Some books were unavailable.', NULL, NULL, 'Student: I''m sorry my essay is late. I wasn''t ill and my computer was fine. I simply couldn''t get hold of two of the books I needed from the library until yesterday.', NULL, NULL, '["C"]'::jsonb, '[{"id": "A", "text": "The student was ill."}, {"id": "B", "text": "The student’s computer broke."}, {"id": "C", "text": "Some books were unavailable."}]'::jsonb),
('ielts-b2-lmcq-010', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Meeting point for the trip', 'Where should students meet on Friday? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "by the main gate". The answer is A: the main gate', NULL, NULL, 'Teacher: Last time we met in the car park, and that caused traffic problems. So on Friday, please meet at the front of the school, by the main gate, not at the sports hall.', NULL, NULL, '["A"]'::jsonb, '[{"id": "A", "text": "the main gate"}, {"id": "B", "text": "the sports hall"}, {"id": "C", "text": "the car park"}]'::jsonb),
