('ielts-b2-lmcq-012', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Why the café closed', 'Why did the café close? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "couldn''t find enough staff". The answer is B: There were not enough staff.', NULL, NULL, 'Owner: People think we closed because of the rent, but the landlord was very fair. Honestly, I just couldn''t find enough staff to keep the café open seven days a week.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "The rent was too high."}, {"id": "B", "text": "There were not enough staff."}, {"id": "C", "text": "There were too few customers."}]'::jsonb),
('ielts-b2-lmcq-013', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'Best time to visit', 'When is the best time to see the birds? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "the best time to come is autumn". The answer is B: autumn', NULL, NULL, 'Ranger: Spring is lovely, but the paths are often muddy. Summer is very crowded. If you want to see the birds, the best time to come is autumn, when thousands arrive from the north.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "summer"}, {"id": "B", "text": "autumn"}, {"id": "C", "text": "spring"}]'::jsonb),
