('ielts-b2-lmcq-041', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'What the museum lacks', 'What does the museum lack? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "information in other languages". The answer is A: multilingual information', NULL, NULL, 'Visitor: The museum has an excellent café and plenty of seating. What it doesn''t have is information in other languages, which is a pity for tourists.', NULL, NULL, '["A"]'::jsonb, '[{"id": "A", "text": "multilingual information"}, {"id": "B", "text": "a café"}, {"id": "C", "text": "seating"}]'::jsonb),
('ielts-b2-lmcq-042', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'How long the course lasts', 'How long does the part-time course usually take? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "which takes two years". The answer is B: two years', NULL, NULL, 'Adviser: The full-time course lasts one year. You can also study part-time, which takes two years. Some students take three, but that''s unusual.', NULL, NULL, '["B"]'::jsonb, '[{"id": "A", "text": "one year"}, {"id": "B", "text": "two years"}, {"id": "C", "text": "three years"}]'::jsonb),
