('ielts-b2-lmcq-047', 'ielts-2026-01', 'IELTS', ARRAY['IELTS'], 'listening', 'ielts-listening-mcq', 'Choose the correct answer', 'What the woman lost', 'What did the woman lose? Choose ONE letter, A, B or C. Synthesised practice audio.', 120, 0, 1, 'medium', ARRAY['Original practice', 'IELTS', 'Listening'], 'The speaker says: "It was my purse I left on the bus". The answer is A: her purse', NULL, NULL, 'Woman: My keys were in my pocket, luckily, and my phone was in my hand. It was my purse I left on the bus.', NULL, NULL, '["A"]'::jsonb, '[{"id": "A", "text": "her purse"}, {"id": "B", "text": "her keys"}, {"id": "C", "text": "her phone"}]'::jsonb),
